/*---------------------------------------------------------------------------
 * Qortex (QAM-511): inert stub for the bundled Copilot Chat extension.
 *
 * Qortex ships a single agent (FenneQ) and does NOT bundle Copilot:
 *   - packaged builds exclude it (build/lib/extensions.ts `excludedExtensions`
 *     + the copilot compile/shim tasks are removed from build/gulpfile.vscode.ts)
 *   - it is dropped from build/npm/dirs.ts so its deps are never installed
 *
 * But the dev-mode extension scanner still reads extensions/copilot (its
 * package.json `main` is ./dist/extension), so without this file a clean
 * checkout shows a missing-module activation error on launch.
 *
 * Committed deliberately (force-added; extensions/copilot/.gitignore ignores
 * dist/). NOT generated by any build — do not delete. Keeping it under dist/
 * means upstream rebases never touch it (upstream never tracks dist/).
 *--------------------------------------------------------------------------*/
exports.activate = function () { };
exports.deactivate = function () { };
